reference<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Bookmarks — prototype</title>
<style>
  :root { --line:#e2e2e6; --muted:#6b7280; --accent:#2563eb; --warn:#b45309; --warnbg:#fff7ed; }
  * { box-sizing: border-box; }
  body { font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
         margin: 0; color: #111; background: #f6f7f9; }
  header { background: #fff; border-bottom: 1px solid var(--line); padding: 16px 24px; }
  header h1 { margin: 0; font-size: 18px; }
  header p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
  main { max-width: 820px; margin: 0 auto; padding: 24px; }
  .card { background: #fff; border: 1px solid var(--line); border-radius: 10px; padding: 16px; margin-bottom: 16px; }
  .row { display: flex; gap: 8px; }
  input[type=text], input[type=url], textarea {
    width: 100%; padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; font-family: inherit; }
  textarea { resize: vertical; min-height: 56px; }
  label { display:block; font-size: 12px; color: var(--muted); margin: 10px 0 4px; }
  button { padding: 9px 15px; border: 0; border-radius: 8px; background: var(--accent); color: #fff;
           font-size: 14px; cursor: pointer; white-space: nowrap; }
  button.secondary { background: #eef1f5; color: #111; }
  button:disabled { opacity: .5; cursor: default; }
  .hint { color: var(--muted); font-size: 12px; margin-top: 6px; }
  .warn { background: var(--warnbg); border: 1px solid #fed7aa; color: var(--warn);
          border-radius: 8px; padding: 12px; font-size: 13px; margin-top: 10px; }
  .list-head { display:flex; justify-content: space-between; align-items:center; margin-bottom: 10px; }
  .list-head h2 { font-size: 15px; margin: 0; }
  .count { color: var(--muted); font-size: 13px; }
  .bm { border: 1px solid var(--line); border-radius: 10px; padding: 14px; margin-bottom: 10px; background:#fff; }
  .bm .title { font-weight: 600; font-size: 15px; }
  .bm .url { color: var(--accent); font-size: 12px; word-break: break-all; text-decoration:none; }
  .bm .desc { color: #374151; font-size: 13px; margin-top: 6px; }
  .bm .note { font-size: 13px; margin-top: 8px; background:#f9fafb; border-left:3px solid #d1d5db; padding:6px 10px; }
  .tags { margin-top: 8px; display:flex; gap:6px; flex-wrap:wrap; }
  .tag { background:#eef2ff; color:#3730a3; font-size:11px; padding:3px 8px; border-radius:999px; }
  .empty { color: var(--muted); font-size: 14px; text-align:center; padding: 24px; }
  .spinner { color: var(--muted); font-size: 13px; }
  .flash { background:#ecfdf5; border:1px solid #a7f3d0; color:#065f46; border-radius:8px; padding:10px; font-size:13px; margin-bottom:12px; }
  .highlight { background: #fde68a; }
  @media (max-width: 520px){ .row { flex-direction: column; } }
</style>
</head>
<body>
<header>
  <h1>My Bookmarks</h1>
  <p>Prototype — core flow: save a link, add your context, find it again.</p>
</header>
<main>
  <div id="flash"></div>

  <div class="card">
    <label for="url">Paste a link to save</label>
    <div class="row">
      <input type="url" id="url" placeholder="https://…" autocomplete="off" />
      <button id="saveBtn">Save link</button>
    </div>
    <div id="saveArea"></div>
  </div>

  <div class="card">
    <label for="search">Search your bookmarks</label>
    <input type="text" id="search" placeholder="Search by title, description, note, tag, or address…" autocomplete="off" />
    <div class="hint">Searches everything you saved, including your notes and tags.</div>
  </div>

  <div class="list-head">
    <h2>Saved</h2>
    <span class="count" id="count"></span>
  </div>
  <div id="list"></div>
</main>

<script>
// ---- Simulated "auto-fill" metadata source (prototype only) ----
// In the real app this comes from fetching the page. Here we fake it so the
// behaviour can be experienced.
const KNOWN = {
  "https://developer.mozilla.org/en-us/docs/web/javascript/closures": {
    title: "Closures - JavaScript | MDN",
    description: "A closure is the combination of a function bundled together with references to its surrounding state."
  },
  "https://reactjs.org/docs/hooks-intro.html": {
    title: "Introducing Hooks – React",
    description: "Hooks let you use state and other React features without writing a class."
  }
};
function autoFill(url){
  const key = url.toLowerCase().replace(/\/+$/,'');
  if (KNOWN[key]) return KNOWN[key];
  // generic fallback derived from the address
  let host = url; try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){}
  let path = ''; try { path = new URL(url).pathname.replace(/[-/_]+/g,' ').trim(); } catch(e){}
  const guess = (path || host).split(' ').filter(Boolean).slice(0,6)
                 .map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');
  return { title: guess ? guess + " — " + host : host, description: "Saved from " + host };
}
function normalize(url){
  try { const u = new URL(url); return (u.hostname.replace(/^www\./,'') + u.pathname.replace(/\/+$/,'') + u.search).toLowerCase(); }
  catch(e){ return url.trim().toLowerCase().replace(/\/+$/,''); }
}

// ---- Store (prototype: in-memory, seeded) ----
let bookmarks = [
  { id: 1, url: "https://developer.mozilla.org/en-US/docs/Web/JavaScript/Closures",
    title: "Closures - JavaScript | MDN",
    description: "A closure is the combination of a function bundled together with references to its surrounding state.",
    tags: ["javascript","reference"], note: "Re-read before the interview — the counter example finally made it click." },
];
let nextId = 2;
let draft = null;      // pending save being edited
let dupOf = null;      // existing bookmark a save duplicates

const $ = s => document.querySelector(s);

function flash(msg){
  $("#flash").innerHTML = '<div class="flash">'+msg+'</div>';
  setTimeout(()=>{ $("#flash").innerHTML=''; }, 4000);
}

function renderSaveArea(){
  const area = $("#saveArea");
  if (dupOf){
    area.innerHTML =
      '<div class="warn">You already saved this address on <b>'+escapeHtml(dupOf.title)+'</b>.'
      + ' Saving again would create a duplicate.'
      + '<div class="row" style="margin-top:10px">'
      + '<button class="secondary" id="viewDup">Show the one I already have</button>'
      + '<button class="secondary" id="cancelDup">Cancel</button>'
      + '</div></div>';
    $("#viewDup").onclick = ()=>{ const t=dupOf; dupOf=null; $("#url").value=''; renderSaveArea();
        flash('Here is the bookmark you already had.'); jumpTo(t.id); };
    $("#cancelDup").onclick = ()=>{ dupOf=null; $("#url").value=''; renderSaveArea(); };
    return;
  }
  if (!draft){ area.innerHTML=''; return; }
  area.innerHTML =
    '<div class="hint" style="margin-top:12px">We filled in the title and description for you — edit anything that\'s off.</div>'
    + '<label>Title</label><input type="text" id="dTitle" value="'+escapeAttr(draft.title)+'">'
    + '<label>Description</label><textarea id="dDesc">'+escapeHtml(draft.description)+'</textarea>'
    + '<label>Tags (comma separated)</label><input type="text" id="dTags" value="'+escapeAttr(draft.tags||'')+'" placeholder="e.g. javascript, reading">'
    + '<label>Your note (why you saved it)</label><textarea id="dNote" placeholder="A line to your future self…">'+escapeHtml(draft.note||'')+'</textarea>'
    + '<div class="row" style="margin-top:12px"><button id="confirmSave">Add to my bookmarks</button>'
    + '<button class="secondary" id="cancelSave">Cancel</button></div>';
  $("#confirmSave").onclick = confirmSave;
  $("#cancelSave").onclick = ()=>{ draft=null; $("#url").value=''; renderSaveArea(); };
}

function startSave(){
  const url = $("#url").value.trim();
  if (!url){ return; }
  dupOf = null; draft = null;
  const existing = bookmarks.find(b => normalize(b.url) === normalize(url));
  if (existing){ dupOf = existing; renderSaveArea(); return; }
  // simulate fetching metadata
  $("#saveArea").innerHTML = '<div class="spinner" style="margin-top:12px">Looking up the page…</div>';
  setTimeout(()=>{
    const meta = autoFill(url);
    draft = { url, title: meta.title, description: meta.description, tags:'', note:'' };
    renderSaveArea();
  }, 500);
}

function confirmSave(){
  const b = {
    id: nextId++,
    url: draft.url,
    title: $("#dTitle").value.trim() || draft.url,
    description: $("#dDesc").value.trim(),
    tags: $("#dTags").value.split(',').map(t=>t.trim()).filter(Boolean),
    note: $("#dNote").value.trim()
  };
  bookmarks.unshift(b);
  draft=null; $("#url").value=''; renderSaveArea();
  flash('Saved. It\'s in your list below.');
  render();
  jumpTo(b.id);
}

function jumpTo(id){
  setTimeout(()=>{
    const el = document.getElementById('bm-'+id);
    if (el){ el.scrollIntoView({behavior:'smooth', block:'center'});
      el.classList.add('highlight'); setTimeout(()=>el.classList.remove('highlight'), 1500); }
  }, 60);
}

function matches(b, q){
  if (!q) return true;
  q = q.toLowerCase();
  return [b.title, b.description, b.note, b.url, (b.tags||[]).join(' ')]
    .some(f => (f||'').toLowerCase().includes(q));
}

function render(){
  const q = $("#search").value.trim();
  const shown = bookmarks.filter(b => matches(b, q));
  $("#count").textContent = shown.length + (shown.length===1?' bookmark':' bookmarks')
     + (q? ' matching "'+q+'"' : '');
  const list = $("#list");
  if (shown.length===0){
    list.innerHTML = '<div class="empty">'
      + (q ? 'No bookmarks match "'+escapeHtml(q)+'".' : 'No bookmarks yet — save your first link above.')
      + '</div>';
    return;
  }
  list.innerHTML = shown.map(b =>
    '<div class="bm" id="bm-'+b.id+'">'
    + '<div class="title">'+escapeHtml(b.title)+'</div>'
    + '<a class="url" href="'+escapeAttr(b.url)+'" target="_blank" rel="noopener">'+escapeHtml(b.url)+'</a>'
    + (b.description ? '<div class="desc">'+escapeHtml(b.description)+'</div>' : '')
    + (b.note ? '<div class="note">'+escapeHtml(b.note)+'</div>' : '')
    + ((b.tags&&b.tags.length) ? '<div class="tags">'+b.tags.map(t=>'<span class="tag">'+escapeHtml(t)+'</span>').join('')+'</div>' : '')
    + '</div>'
  ).join('');
}

function escapeHtml(s){ return (s||'').replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
function escapeAttr(s){ return (s||'').replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

$("#saveBtn").onclick = startSave;
$("#url").addEventListener('keydown', e=>{ if(e.key==='Enter') startSave(); });
$("#search").addEventListener('input', render);

render();
document.body.setAttribute('data-harness-ready','true');
</script>
</body>
</html>

