299:$("#search").addEventListener('input', render);
// a differently-capitalized duplicate ("Javascript" -> existing "javascript")
function canonTag(t){
  const hit = allTags().find(e => e.toLowerCase() === t.toLowerCase());
  return hit || t;
}
function confirmSave(){
  const seen = new Set(); const tags = [];
  $("#dTags").value.split(',').map(t=>t.trim()).filter(Boolean).forEach(t=>{
    const c = canonTag(t); const k = c.toLowerCase();
    if(!seen.has(k)){ seen.add(k); tags.push(c); }
  });
  const b = { id: nextId++, url: draft.url,
    title: $("#dTitle").value.trim() || draft.url,
    description: $("#dDesc").value.trim(),
    favicon: draft.favicon, preview: draft.preview,
    tags: tags,
    note: $("#dNote").value.trim() };
  bookmarks.unshift(b);
  draft=null; $("#url").value=''; renderSaveArea();
  flash('Saved. It\'s in your list below.'); render(); jumpTo(b.id);
}

function jumpTo(id){ setTimeout(()=>{ const el=document.getElementById('bm-'+id);
  if(el){ el.scrollIntoView({behavior:'smooth',block:'center'});
    el.classList.add('highlight'); setTimeout(()=>el.classList.remove('highlight'),1500); } }, 60); }

function matches(b, q){ if(!q) return true; q=q.toLowerCase();
  return [b.title,b.description,b.note,b.url,(b.tags||[]).join(' ')].some(f=>(f||'').toLowerCase().includes(q)); }

function render(){
  const q=$("#search").value.trim();
  const shown=bookmarks.filter(b=>matches(b,q));
  $("#count").textContent = shown.length + (shown.length===1?' bookmark':' bookmarks') + (q?' matching "'+q+'"':'');
  const list=$("#list");
  if(!shown.length){ list.innerHTML='<div class="empty">'
      + (q?'No bookmarks match "'+escapeHtml(q)+'".':'No bookmarks yet — save your first link above.') + '</div>'; return; }
  list.innerHTML = shown.map(b =>
    '<div class="bm" id="bm-'+b.id+'">'
    + '<div class="preview"><img src="'+b.preview+'" alt=""></div>'
    + '<div class="body">'
    + '<div class="titleline"><img class="favicon" src="'+b.favicon+'" alt=""><span class="title">'+escapeHtml(b.title)+'</span></div>'
    + '<a class="url" href="'+escapeAttr(b.url)+'" target="_blank" rel="noopener">'+escapeHtml(b.url)+'</a>'
    + (b.description?'<div class="desc">'+escapeHtml(b.description)+'</div>':'')
    + (b.note?'<div class="note">'+formatNote(b.note)+'</div>':'')
    + ((b.tags&&b.tags.length)?'<div class="tags">'+b.tags.map(t=>'<span class="tag">'+escapeHtml(t)+'</span>').join('')+'</div>':'')
    + '</div></div>'
  ).join('');
}

function escapeHtml(s){ return (s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
function escapeAttr(s){ return (s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

$("#saveBtn").onclick = startSave;
$("#url").addEventListener('keydown', e=>{ if(e.key==='Enter') startSave(); });
$("#search").addEventListener('input', render);

render();
document.body.setAttribute('data-harness-ready','true');
</script>
</body>
</html>

