function flash(msg){ $("#flash").innerHTML='<div class="flash">'+msg+'</div>';
  setTimeout(()=>{ $("#flash").innerHTML=''; }, 4000); }

// very small formatter: **bold**, lines starting with - become bullets, blank line = paragraph
function formatNote(txt){
  const lines=(txt||'').split('\n'); let html=''; let inList=false;
  const inline=s=>{
    // escape first (safety), then apply simple, safe markdown
    let out=escapeHtml(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>');
    // [text](url) — only http/https links, opened safely
    out=out.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
      (m,txt,url)=>'<a href="'+escapeAttr(url)+'" target="_blank" rel="noopener noreferrer">'+txt+'</a>');
    return out;
  };
  for(const raw of lines){ const l=raw.trim();
    if(l.startsWith('- ')){ if(!inList){html+='<ul>';inList=true;} html+='<li>'+inline(l.slice(2))+'</li>'; }
