      if(tk.t==='op'||tk.t==='('||tk.t==='not'){ const r=parseNot(); const a=l,b=r; l=x=>a(x)&&b(x); continue; }
      break; }
    return l; }
  function parseNot(){ if(peek()&&peek().t==='not'){ next(); const r=parseNot(); return x=>!r(x); }
    return parsePrimary(); }
  function parsePrimary(){ const tk=peek();
    if(!tk) return ()=>true;
    if(tk.t==='('){ next(); const e=parseOr(); if(peek()&&peek().t===')') next(); return e; }
    if(tk.t==='op'){ next(); return operand(tk); }
    next(); return ()=>true; }
  function operand(tk){ const v=(tk.v||'').toLowerCase();
    if(tk.kind==='tag') return b=> (b.tags||[]).some(t=>t.toLowerCase()===v);
    // word / phrase: search across all fields including tags
    return b=> [b.title,b.description,b.note,b.url,(b.tags||[]).join(' ')]
