function saveEdit(){
  const b=bookmarks.find(x=>x.id===editingId); if(!b) return;
  const newUrl=$("#eUrl").value.trim() || b.url;
  // if the address now matches a DIFFERENT bookmark, block (avoid duplicate)
  const clash=bookmarks.find(x=>x.id!==b.id && normalize(x.url)===normalize(newUrl));
  if(clash){ $("#eDupWarn").innerHTML='<div class="warn">That address is already saved as <b>'
      +escapeHtml(clash.title)+'</b>. Two bookmarks can\'t share the same address.</div>'; return; }
  const seen=new Set(); const tags=[];
  $("#eTags").value.split(',').map(t=>t.trim()).filter(Boolean).forEach(t=>{
    const c=canonTag(t); const k=c.toLowerCase(); if(!seen.has(k)){ seen.add(k); tags.push(c); } });
  const urlChanged = normalize(newUrl)!==normalize(b.url);
  b.url=newUrl; b.title=$("#eTitle").value.trim()||newUrl;
  b.description=$("#eDesc").value.trim(); b.tags=tags; b.note=$("#eNote").value.trim();
  if(urlChanged){ b.favicon=faviconFor(newUrl); b.preview=previewFor(newUrl,b.title); }
  editingId=null; flash('Changes saved.'); render(); jumpTo(b.id);
}

