  function draw(){
    const val=field.value; const tokens=val.split(',');
    const cur=tokens[tokens.length-1].trim().toLowerCase();
    const already=tokens.slice(0,-1).map(t=>t.trim().toLowerCase());
    const cand=allTags().filter(t=> !already.includes(t.toLowerCase())
        && (cur==='' ? true : t.toLowerCase().includes(cur)) && t.toLowerCase()!==cur);
    if(!cand.length){ box.innerHTML=''; return; }
    box.innerHTML='<span class="lbl">Tags you already use:</span>'
      + cand.slice(0,8).map(t=>'<button type="button" class="stag" data-t="'+escapeAttr(t)+'">'+escapeHtml(t)+'</button>').join('');
    box.querySelectorAll('.stag').forEach(btn=>btn.onclick=()=>{
      tokens[tokens.length-1]=' '+btn.dataset.t; field.value=tokens.join(',').replace(/^ /,'')+', ';
      field.focus(); draw();
    });
  }
  field.addEventListener('input', draw); field.addEventListener('focus', draw); draw();
}

